import { test } from "node:test";
import assert from "node:assert/strict";
import { PartitionedTopic, TransientSendError } from "../src/bus/topic.ts";
import { StatusPublisher, type OrderStatus, type StatusEvent } from "../src/orders/statusPublisher.ts";
import { TrackingProjection } from "../src/orders/tracking.ts";

const LIFECYCLE: OrderStatus[] = ["placed", "accepted", "preparing", "picked_up", "delivered"];

function setup(partitions = 4) {
    const topic = new PartitionedTopic<StatusEvent>(partitions);
    const publisher = new StatusPublisher(topic);
    const pushes: [string, string][] = [];
    const tracking = new TrackingProjection(topic, (orderId, text) => pushes.push([orderId, text]));
    return { topic, publisher, tracking, pushes };
}

const events = (orderId: string, statuses = LIFECYCLE): StatusEvent[] =>
    statuses.map((status, i) => ({ orderId, status, at: `2026-11-19T18:${String(10 + i).padStart(2, "0")}:00Z` }));

// Reject the given (orderId, status) sends once each with a transient error.
function failOnce(topic: PartitionedTopic<StatusEvent>, ...which: [string, OrderStatus][]) {
    const left = new Set(which.map(([o, s]) => `${o}/${s}`));
    topic.failWhen = (_, m) => (left.delete(`${m.orderId}/${m.status}`) ? new TransientSendError("NOT_LEADER_FOR_PARTITION") : null);
}

test("an order's updates reach the tracking page in the order they happened", async () => {
    const { publisher, tracking } = setup();
    for (const e of [...events("A-1"), ...events("B-2", ["placed", "cancelled"])]) publisher.enqueue(e);
    await publisher.flushAll();
    tracking.poll();
    assert.deepEqual(tracking.timeline("A-1"), LIFECYCLE);
    assert.equal(tracking.statusOf("B-2"), "cancelled");
});

test("every update for one order goes to the same partition", async () => {
    const { topic, publisher } = setup(8);
    for (const e of events("A-1")) publisher.enqueue(e);
    await publisher.flushAll();
    const used = topic.partitions.map((p, i) => (p.length ? i : -1)).filter((i) => i >= 0);
    assert.deepEqual(used, [topic.partitionFor("A-1")]);
});

test("a transient send failure doesn't reorder an order's updates", async () => {
    const { topic, publisher, tracking } = setup();
    failOnce(topic, ["A-1", "accepted"]);
    for (const e of events("A-1")) publisher.enqueue(e);
    await publisher.flushAll();
    tracking.poll();
    console.log("timeline seen by the customer:", tracking.timeline("A-1"));
    assert.deepEqual(tracking.timeline("A-1"), LIFECYCLE);
});

test("after a flaky send, a delivered order shows as delivered", async () => {
    const { topic, publisher, tracking } = setup();
    failOnce(topic, ["A-1", "picked_up"]);
    for (const e of events("A-1")) publisher.enqueue(e);
    await publisher.flush();
    tracking.poll();
    await publisher.flushAll();
    tracking.poll();
    assert.equal(tracking.statusOf("A-1"), "delivered");
});

test("customers get push notifications in lifecycle order even when sends are retried", async () => {
    const { topic, publisher, tracking, pushes } = setup(1);
    failOnce(topic, ["A-1", "placed"], ["B-2", "accepted"]);
    for (let i = 0; i < 3; i++) {
        publisher.enqueue(events("A-1")[i]);
        publisher.enqueue(events("B-2")[i]);
    }
    await publisher.flushAll();
    tracking.poll();
    const forOrder = (id: string) => pushes.filter(([o]) => o === id).map(([, text]) => text);
    assert.deepEqual(forOrder("A-1"), forOrder("B-2"));
    assert.deepEqual(forOrder("A-1")[0], "We've sent your order to the restaurant");
});

test("updates that hit a transient error are kept and sent later, none lost", async () => {
    const { topic, publisher } = setup();
    failOnce(topic, ["A-1", "preparing"], ["C-3", "placed"]);
    for (const e of [...events("A-1"), ...events("C-3")]) publisher.enqueue(e);
    await publisher.flushAll();
    assert.equal(publisher.pendingCount(), 0);
    assert.equal(topic.partitions.flat().length, 10);
});

test("a non-transient broker error is raised to the caller", async () => {
    const { topic, publisher } = setup();
    topic.failWhen = () => new Error("message too large");
    publisher.enqueue(events("A-1")[0]);
    await assert.rejects(publisher.flush(), /message too large/);
});
